use std::{fs, path::{Path, PathBuf}};

#[derive(Clone,Debug,PartialEq,Eq)] pub struct SteamInstall { pub app_id:u32, pub title:String, pub install_path:PathBuf, pub available:bool }
fn quoted(source:&str,key:&str)->Option<String>{let needle=format!("\"{key}\"");let start=source.find(&needle)?+needle.len();let rest=&source[start..];let first=rest.find('"')?+1;let after=&rest[first..];let end=after.find('"')?;Some(after[..end].to_string())}
pub fn discover_installed_games(steam_root:&Path)->Result<Vec<SteamInstall>,String>{let apps=steam_root.join("steamapps");if !apps.is_dir(){return Err("biblioteca Steam não encontrada".into())}let mut games=Vec::new();for entry in fs::read_dir(&apps).map_err(|_|"não foi possível ler a biblioteca Steam".to_string())?{let path=entry.map_err(|_|"manifesto Steam inválido".to_string())?.path();if !path.file_name().and_then(|n|n.to_str()).is_some_and(|n|n.starts_with("appmanifest_")&&n.ends_with(".acf")){continue}let data=fs::read_to_string(&path).map_err(|_|"manifesto Steam inválido".to_string())?;let app_id=quoted(&data,"appid").and_then(|v|v.parse().ok()).ok_or("AppID Steam inválido")?;let title=quoted(&data,"name").filter(|v|!v.trim().is_empty()).ok_or("nome Steam inválido")?;let dir=quoted(&data,"installdir").ok_or("diretório Steam inválido")?;let install_path=apps.join("common").join(dir);games.push(SteamInstall{app_id,title,available:install_path.is_dir(),install_path});}Ok(games)}
